package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.*;import com.ryanjei.orushio.pve.persistence.ActiveSessionRepository;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class DefaultMapAdministrationServiceTest{@TempDir Path temp;@Test void setupStartPointAreaSaveAndDiscard()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();assertTrue(f.service.startSetup("map-a",admin,"IDLE").active());f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,new BlockPoint(1,2,3,0,0),true);f.service.selectField(admin,"enemyZones",true);f.service.recordClick(admin,new BlockPoint(0,0,0,0,0),false);f.service.recordClick(admin,new BlockPoint(2,3,4,0,0),true);String session=f.games.current().sessionId().toString();MapProfile saved=f.service.saveSetup(session);assertEquals(1,saved.points().get("farmSpawn").size());assertEquals(1,saved.areas().get("enemyZones").size());assertEquals(GameState.IDLE,f.games.current().state());assertFalse(Files.exists(f.gateway.last.directory()));f.service.startSetup("map-a",admin,"IDLE");f.service.selectField(admin,"shopPoints",false);f.service.recordClick(admin,new BlockPoint(9,9,9,0,0),true);f.service.discardSetup(f.games.current().sessionId().toString());assertNull(f.repository.find(new MapProfileId("map-a")).orElseThrow().points().get("shopPoints"));}@Test void ownedMapDeleteRemovesFilesAndProfile()throws Exception{Fixture f=fixture();f.service.delete("map-a");assertFalse(Files.exists(temp.resolve("maps/map-a")));assertTrue(f.repository.find(new MapProfileId("map-a")).isEmpty());}@Test void deleteRefusesMissingOwnershipMarker()throws Exception{Fixture f=fixture();Files.delete(temp.resolve("maps/map-a/.orushio-map-owner"));assertThrows(IllegalStateException.class,()->f.service.delete("map-a"));assertTrue(Files.exists(temp.resolve("maps/map-a/template/level.dat")));assertTrue(f.repository.find(new MapProfileId("map-a")).isPresent());}@Test void unauthorizedPlayerIsRejected()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");assertThrows(SecurityException.class,()->f.service.selectField(UUID.randomUUID(),"farmSpawn",false));}private Fixture fixture()throws Exception{Path maps=temp.resolve("maps"),worlds=temp.resolve("worlds"),template=maps.resolve("map-a/template");Files.createDirectories(template);Files.writeString(template.resolve("level.dat"),"x");Files.writeString(maps.resolve("map-a/.orushio-map-owner"),"map-a");MemoryProfiles profiles=new MemoryProfiles();profiles.save(MapProfileTest.empty("map-a"));DefaultGameApplicationService games=new DefaultGameApplicationService(new MemorySession());FakeWorld gateway=new FakeWorld();TemporaryWorldManager manager=new TemporaryWorldManager(maps,worlds);var service=new DefaultMapAdministrationService(maps,profiles,new SafeWorldZipImporter(maps,SafeWorldZipImporter.Limits.defaults()),manager,gateway,games,new MapSelectionService(new Random(1)));return new Fixture(service,profiles,games,gateway);}private record Fixture(DefaultMapAdministrationService service,MemoryProfiles repository,DefaultGameApplicationService games,FakeWorld gateway){}private static final class MemoryProfiles implements MapProfileRepository{final Map<MapProfileId,MapProfile> values=new HashMap<>();public List<MapProfile> findAll(){return List.copyOf(values.values());}public Optional<MapProfile> find(MapProfileId id){return Optional.ofNullable(values.get(id));}public void save(MapProfile p){values.put(p.mapId(),p);}public void delete(MapProfileId id){values.remove(id);}}private static final class MemorySession implements ActiveSessionRepository{GameSession value;public Optional<GameSession> load(){return Optional.ofNullable(value);}public void save(GameSession s){value=s;}}private static final class FakeWorld implements MapWorldGateway{TemporaryWorldManager.OwnedWorld last;public void loadForSetup(TemporaryWorldManager.OwnedWorld w,UUID a){last=w;}public void unload(TemporaryWorldManager.OwnedWorld w){assertEquals(last,w);}}}
